'use strict';

/**
 * BUG-151 part 2 — a UUID made in the browser, generated by the script ("uuid" correlation):
 *  - the Advisor finds UUIDs sent in a header or the query string (Phase 3b), marks them browser-made, and a card set
 *    to generate (_gen) becomes { extractorType: "uuid", sourceIdx: -1, extractorConfig: { value } }
 *  - VuGen: perfx_uuid() once at the top of Action.c (seeded once per Vuser), a call before the first request that
 *    sends each recorded value — a value the recording renewed is renewed at the same places, one it kept is kept
 *  - DevWeb: load.global.<name> = load.utils.uuid() before that request, never inside Promise.all
 *  - no recorded UUID is left in either script
 */

const fs = require('fs');
const path = require('path');

const PUB = path.resolve(__dirname, '../../src/web/public');
const read = (f) => fs.readFileSync(path.join(PUB, f), 'utf-8').replace(/^﻿/, '');
global.RequestFilter = require('../../src/web/public/shared/request-filter.js');
global.VugenCodegen = require('../../src/web/public/shared/vugen-codegen.js');
global.PageResources = require('../../src/web/public/shared/page-resources.js');
global.HostParams = require('../../src/web/public/shared/host-params.js');

function engine() {
  const doc = { documentElement: { setAttribute() {}, classList: { add() {} } }, getElementById: () => null, querySelectorAll: () => [], querySelector: () => null };
  const src = ['VuGen-Script-Studio-constants.js', 'VuGen-Script-Studio-correlation.js', 'studio-advisor.js', 'studio-codegen.js', 'studio-ui.js'].map(read).join('\n') +
    '\nfunction regenerateFromAdvisor() {}\nfunction showToast() {}';
  // eslint-disable-next-line no-new-func
  return new Function('document', 'window', 'localStorage', src +
    '\nreturn { S, genActionC, genMainJS, advisorScan, advisorToCorrelation, advisorSetGenerate, advisorCanGenerate };')(doc, { location: { pathname: '/converter/studio' }, addEventListener() {} }, { getItem: () => null, setItem() {} });
}

let nextId = 1;
function ent(url, o = {}) {
  return Object.assign({
    id: nextId++, url, method: 'GET', status: 200, ct: 'application/json', dur: 50, startMs: 0,
    reqHdrs: [], hdrsMap: {}, respHdrsMap: {}, body: null, referer: '', _resourceType: 'xhr', respBody: '{"ok":true}',
    isMarker: false, filtered: false,
  }, o);
}
const U1 = '1b4e28ba-2fa1-41d2-883f-0016d3cca427';   // X-Request-Id of the first call
const U2 = '6fa459ea-ee8a-4ca4-894e-db77e160355e';   // X-Request-Id of the second call (renewed)
const T = '9c858901-8a57-4791-81fe-4c455b099bc9';    // traceId: one value for the whole journey
const hdr = (v) => ({ reqHdrs: [{ name: 'X-Request-Id', value: v }], hdrsMap: { 'x-request-id': v } });
const json = (o) => ({ mimeType: 'application/json', text: JSON.stringify(o) });
const recording = () => [
  ent('https://shop.example.com/', { ct: 'text/html', _resourceType: 'document', respBody: '<html>shop</html>' }),
  ent('https://shop.example.com/api/a', Object.assign({ method: 'POST', body: json({ traceId: T, item: 'shoes' }), startMs: 1000 }, hdr(U1))),
  ent('https://shop.example.com/api/b?cid=' + T, Object.assign({ method: 'POST', body: json({ traceId: T, qty: 2 }), startMs: 2000 }, hdr(U2))),
  ent('https://shop.example.com/api/c?cid=' + T, { startMs: 3000 }),
];

function scanned() {
  const E = engine(), S = E.S;
  Object.assign(S, { format: 'both', entries1: recording(), txns: [], params: [], correlations: [], hostNames: {} });
  E.advisorScan(S.entries1, []);
  return { E, S };
}

describe('the Advisor: UUIDs made in the browser', () => {
  test('header and query UUIDs are found (Phase 3b), body ones by Phase 3; all browser-made and named by their field', () => {
    const { S } = scanned();
    const by = Object.fromEntries(S.advisorCandidates.map((c) => [c.value, c]));
    expect(by[U1] && by[U1]._browser).toBe(true);
    expect(by[U2] && by[U2]._browser).toBe(true);
    expect(by[T] && by[T]._browser).toBe(true);
    expect(by[U1].varName).toBe('xRequestId');
    expect(by[U1].usages.map((u) => [u.entryIdx, u.location, u.jsonPath])).toEqual([[1, 'header', 'X-Request-Id']]);
    // every place it is sent: the two JSON bodies and the two query strings
    expect(by[T].usages.map((u) => [u.entryIdx, u.location]).sort()).toEqual([[1, 'body_json'], [2, 'body_json'], [2, 'query'], [3, 'query']]);
    expect(by[T].usages.filter((u) => u.location === 'query').every((u) => u.jsonPath === 'cid')).toBe(true);
  });

  test('a cookie, a referer or an authorization header is never a card; a UUID from a response is not browser-made', () => {
    const E = engine(), S = E.S;
    const es = [
      ent('https://shop.example.com/api/id', { respBody: JSON.stringify({ id: U1 }) }),
      ent('https://shop.example.com/api/x', { reqHdrs: [{ name: 'Cookie', value: U2 }, { name: 'Referer', value: T }, { name: 'X-Order', value: U1 }], hdrsMap: { cookie: U2, referer: T, 'x-order': U1 } }),
    ];
    E.advisorScan(es, []);
    const vals = S.advisorCandidates.map((c) => c.value);
    expect(vals).not.toContain(U2);
    expect(vals).not.toContain(T);
    const c = S.advisorCandidates.find((x) => x.value === U1);
    expect(c && c._browser).toBeFalsy();
  });

  test('Generate a UUID: only for a browser-made UUID; it becomes a "uuid" correlation with no source', () => {
    const { E, S } = scanned();
    const c = S.advisorCandidates.find((x) => x.value === U1);
    expect(E.advisorCanGenerate(c)).toBe(true);
    E.advisorSetGenerate(c.id, true);
    expect(c.status).toBe('accepted');
    const corr = E.advisorToCorrelation(c);
    expect([corr.name, corr.extractorType, corr.sourceIdx, corr.extractorConfig]).toEqual(['xRequestId', 'uuid', -1, { value: U1 }]);
    expect(corr.usages[0]).toMatchObject({ reqIdx: 1, location: 'header', key: 'X-Request-Id', tokenValue: U1 });
    E.advisorSetGenerate(c.id, false);
    expect(c.status).toBe('pending');
    expect(c._gen).toBeUndefined();
  });
});

describe('the scripts', () => {
  function generated() {
    const { E, S } = scanned();
    S.advisorCandidates.forEach((c) => { if (E.advisorCanGenerate(c)) E.advisorSetGenerate(c.id, true); });
    const corrs = S.advisorCandidates.filter((c) => c._gen).map(E.advisorToCorrelation);
    S.correlations = corrs;
    return { ac: E.genActionC(S.entries1, corrs), mj: E.genMainJS(S.entries1, corrs), corrs };
  }
  const count = (s, x) => s.split(x).length - 1;

  test('VuGen: the helper once, a new value before the first request that sends each recorded one', () => {
    const { ac } = generated();
    expect(count(ac, 'void perfx_uuid(char *name)')).toBe(1);
    expect(ac).toContain('srand((unsigned int)time(0) ^ (unsigned int)(id * 7919));');
    expect(count(ac, 'perfx_uuid("xRequestId");')).toBe(2);   // renewed, as recorded
    expect(count(ac, 'perfx_uuid("traceId");')).toBe(1);      // kept for the iteration
    const a = ac.indexOf('perfx_uuid("xRequestId");'), reqA = ac.indexOf('/api/a'), b = ac.indexOf('perfx_uuid("xRequestId");', a + 1), reqB = ac.indexOf('/api/b');
    expect(a).toBeLessThan(reqA);
    expect(b).toBeGreaterThan(reqA);
    expect(b).toBeLessThan(reqB);
    expect(ac.indexOf('perfx_uuid("traceId");')).toBeLessThan(reqA);
    expect(ac).toContain('web_add_header("X-Request-Id", "{xRequestId}");');
    expect(ac).toContain('cid={traceId}');
    [U1, U2, T].forEach((v) => expect(ac).not.toContain(v));
  });

  test('DevWeb: load.utils.uuid() before the request, outside Promise.all; the uses read load.global', () => {
    const { mj } = generated();
    expect(count(mj, 'load.global.xRequestId = load.utils.uuid();')).toBe(2);
    expect(count(mj, 'load.global.traceId = load.utils.uuid();')).toBe(1);
    expect(mj).toContain('${load.global.xRequestId}');
    expect(mj).toContain('${load.global.traceId}');
    expect(mj).not.toContain('Promise.all');
    expect(mj).not.toMatch(/new load\.\w*Extractor\("(xRequestId|traceId)"/);
    [U1, U2, T].forEach((v) => expect(mj).not.toContain(v));
    expect(() => new Function('load', mj.replace(/^(import|export)\b.*$/gm, '').replace(/\bawait\b/g, ''))).not.toThrow();   // eslint-disable-line no-new-func
  });

  test('nothing else changes: with no "uuid" correlation the scripts have no helper and no call', () => {
    const E = engine(), S = E.S;
    Object.assign(S, { format: 'both', entries1: recording(), txns: [], params: [], correlations: [], hostNames: {} });
    const ac = E.genActionC(S.entries1, []), mj = E.genMainJS(S.entries1, []);
    expect(ac).not.toContain('perfx_uuid');
    expect(mj).not.toContain('load.utils.uuid()');
  });
});
